using System;
using System.Linq;
using System.Collections.Generic;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.IO;
using System.Windows.Forms;
using System.Xml.Serialization;
namespace IDSketcher {
public class ToolPreset {
    public bool SmoothEnabled=true;public bool Predictive;public int Prediction=50;
    public string Tool="Pencil",Pressure="Simulated pressure";
    public int Size=5,Opacity=100,Flow=100,Hardness=100,Smoothing=50,Taper=50,Colour=unchecked((int)0xff333333);
    public int MinSize {get{return Tool=="Pencil"||Tool=="Pen"||Tool=="Ink Pen"?2:Tool=="Marker"||Tool=="Paintbrush"?5:1;}}
    public int MaxSize {get{return Tool=="Airbrush"?500:MinSize==2?20:Tool=="Marker"?100:Tool=="Paintbrush"?150:200;}}
    public void Normalize(){Size=Math.Max(MinSize,Math.Min(MaxSize,Size));}
    public ToolPreset Copy(){return (ToolPreset)MemberwiseClone();}
    public bool Valid(){return Array.IndexOf(new[]{"Select","Pencil","Pen","Ink Pen","Marker","Airbrush","Paintbrush","Eraser"},Tool)>=0&&Array.IndexOf(new[]{"No pressure","Simulated pressure","Wacom pressure"},Pressure)>=0&&Size>=1&&Size<=500&&Opacity>=0&&Opacity<=100&&Flow>=0&&Flow<=100&&Hardness>=0&&Hardness<=100&&Smoothing>=0&&Smoothing<=100&&Taper>=0&&Taper<=100&&Prediction>=1&&Prediction<=100;}
}
public class Favourite {public int Slot;public ToolPreset Preset;}
public class ToolPreferences { public System.Collections.Generic.List<int> Palette=new System.Collections.Generic.List<int>();public int VectorSpacing=12;public int VectorSpacingPercent=10;
    public List<ToolPreset> Tools=new List<ToolPreset>();
    public List<Favourite> Favourites=new List<Favourite>();
    public static ToolPreferences Load(string path){if(!File.Exists(path))return new ToolPreferences();using(var f=File.OpenRead(path)){var p=(ToolPreferences)new XmlSerializer(typeof(ToolPreferences)).Deserialize(f);if(p.Palette==null)p.Palette=new List<int>();if(p.Palette.Count>48)throw new InvalidDataException("Invalid saved colour palette");if(p.Tools==null||p.Favourites==null||p.Tools.Count>8||p.Favourites.Count>24)throw new InvalidDataException("Invalid tool settings");var names=new HashSet<string>();foreach(var t in p.Tools)if(t==null||!t.Valid()||!names.Add(t.Tool))throw new InvalidDataException("Invalid tool settings");var slots=new HashSet<int>();foreach(var t in p.Favourites)if(t==null||t.Slot<0||t.Slot>=24||!slots.Add(t.Slot)||t.Preset==null||!t.Preset.Valid())throw new InvalidDataException("Invalid favourite");foreach(var t in p.Tools)t.Normalize();foreach(var t in p.Favourites)t.Preset.Normalize();return p;}}
    public void Save(string path){Directory.CreateDirectory(Path.GetDirectoryName(path));string temp=path+".tmp";try{using(var f=File.Create(temp))new XmlSerializer(typeof(ToolPreferences)).Serialize(f,this);if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}finally{if(File.Exists(temp))File.Delete(temp);}}
}
static class ToolIcons {
    public static void Draw(Graphics g,string tool,Rectangle box){var state=g.Save();g.SmoothingMode=SmoothingMode.AntiAlias;g.TranslateTransform(box.X,box.Y);g.ScaleTransform(box.Width/32f,box.Height/32f);
        using(var outline=new Pen(Color.FromArgb(45,58,72),1.4f))using(var body=new SolidBrush(tool=="Pencil"?Color.FromArgb(235,184,62):tool=="Marker"?Color.FromArgb(109,182,158):tool=="Eraser"?Color.FromArgb(224,137,157):Color.FromArgb(114,158,208))){
            if(tool=="Paintbrush"){var st=g.Save();g.TranslateTransform(16,16);g.RotateTransform(40);g.FillRectangle(Brushes.Sienna,-2,-14,4,17);g.DrawRectangle(outline,-2,-14,4,17);g.FillRectangle(Brushes.Silver,-4,0,8,5);g.DrawRectangle(outline,-4,0,8,5);PointF[] bristles={new PointF(-4,5),new PointF(4,5),new PointF(6,14),new PointF(-6,14)};g.FillPolygon(Brushes.SandyBrown,bristles);g.DrawPolygon(outline,bristles);g.DrawLine(outline,-1,6,-2,13);g.DrawLine(outline,2,6,3,13);g.Restore(st);}
            else if(tool=="Airbrush"){g.FillRectangle(body,3,12,16,7);g.DrawRectangle(outline,3,12,16,7);g.DrawLine(outline,10,19,7,29);g.DrawLine(outline,9,12,9,7);g.DrawLine(outline,19,15,24,15);for(int i=0;i<5;i++)g.FillEllipse(Brushes.Teal,25+i%2*3,5+i*4,2,2);}else if(tool=="Eraser"){PointF[] p={new PointF(5,21),new PointF(17,5),new PointF(28,13),new PointF(16,29)};g.FillPolygon(body,p);g.DrawPolygon(outline,p);g.DrawLine(outline,10,15,22,23);}
            else if(tool=="Ink Pen"){PointF[] p={new PointF(5,27),new PointF(11,10),new PointF(23,3),new PointF(29,9),new PointF(22,21)};g.FillPolygon(body,p);g.DrawPolygon(outline,p);g.DrawLine(outline,5,27,18,14);g.FillEllipse(Brushes.White,16,11,4,4);}
            else {float w=tool=="Marker"?6:3.5f;var st=g.Save();g.TranslateTransform(16,16);g.RotateTransform(40);g.FillRectangle(body,-w,-13,w*2,21);g.DrawRectangle(outline,-w,-13,w*2,21);PointF[] tip={new PointF(-w,8),new PointF(w,8),new PointF(tool=="Marker"?w:0,15)};g.FillPolygon(tool=="Pencil"?Brushes.Bisque:Brushes.SlateGray,tip);g.DrawPolygon(outline,tip);if(tool=="Pen")g.DrawLine(outline,w+2,-11,w+2,0);g.Restore(st);}
        }g.Restore(state);
    }
    public static Bitmap Image(string tool){var b=new Bitmap(24,24);using(var g=Graphics.FromImage(b))Draw(g,tool,new Rectangle(0,0,24,24));return b;}
}
class FavouriteButton : Button {
    public Favourite Favourite;public int Slot;
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(Favourite!=null)ToolIcons.Draw(e.Graphics,Favourite.Preset.Tool,new Rectangle(12,3,29,29));else TextRenderer.DrawText(e.Graphics,"+",Font,new Rectangle(0,0,Width,Height-8),ForeColor,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter);TextRenderer.DrawText(e.Graphics,(Slot+1).ToString(),Font,new Rectangle(Width-23,Height-17,21,15),ForeColor,TextFormatFlags.Right);}
}
partial class Studio {
    public void TestNewTool(){SelectTool("Paintbrush");size.Value=31;flow.Value=28;hardness.Value=54;SelectTool("Pen");canvas.Focus();Message m=new Message();ProcessCmdKey(ref m,Keys.P);if(canvas.Tool!="Pencil")throw new Exception("P selects Pencil");ProcessCmdKey(ref m,Keys.P);if(canvas.Tool!="Paintbrush"||size.Value!=31||flow.Value!=28||hardness.Value!=54||toolButtons["Paintbrush"].Image==null)throw new Exception("P cycles to Paintbrush with settings and icon");ProcessCmdKey(ref m,Keys.N);if(canvas.Tool!="Pen")throw new Exception("N selects Pen");SelectTool("Paintbrush");PinFavourite(0);var f=preferences.Favourites[0];if(f.Preset.Tool!="Paintbrush"||!f.Preset.Valid())throw new Exception("Paintbrush favourite");SelectTool("Eraser");ChooseFavourite(f);if(canvas.Tool!="Paintbrush"||size.Value!=31)throw new Exception("Paintbrush recall");preferences.Favourites.Clear();dirty=false;}
    ToolPreferences preferences=new ToolPreferences();string preferencePath;string preferenceError;
    Dictionary<string,ToolPreset> toolSettings=new Dictionary<string,ToolPreset>();bool toolReady;
    ToolPreset CaptureTool(){return new ToolPreset{SmoothEnabled=smoothingEnabled.Checked,Predictive=canvas.Predictive,Prediction=canvas.Prediction,Tool=canvas.Tool,Size=(int)size.Value,Opacity=(int)opacity.Value,Flow=(int)flow.Value,Hardness=(int)hardness.Value,Smoothing=smoothingSlider.Value,Pressure=pressureMode.Text,Taper=taperSlider.Value,Colour=canvas.Ink.ToArgb()};}
    void SetToolSizeRange(ToolPreset p){p.Normalize();sizeSlider.Minimum=1;sizeSlider.Maximum=500;size.Minimum=1;size.Maximum=500;size.Value=p.Size;size.Minimum=p.MinSize;size.Maximum=p.MaxSize;sizeSlider.Minimum=p.MinSize;sizeSlider.Maximum=p.MaxSize;}
    void ApplyTool(ToolPreset p){SetToolSizeRange(p);smoothingEnabled.Checked=p.SmoothEnabled;predictiveToggle.Checked=p.Predictive;predictionSlider.Value=p.Prediction;opacity.Value=p.Opacity;flow.Value=p.Flow;hardness.Value=p.Hardness;smoothingSlider.Value=p.Smoothing;pressureMode.SelectedItem=p.Pressure;taperSlider.Value=p.Taper;canvas.BrushSize=(float)size.Value;canvas.BrushOpacity=p.Opacity/100f;canvas.BrushFlow=p.Flow/100f;canvas.BrushHardness=p.Hardness/100f;canvas.Smoothing=p.SmoothEnabled?p.Smoothing:0;canvas.PressureMode=p.Pressure;canvas.TaperPercent=p.Taper;canvas.Ink=Color.FromArgb(p.Colour);wheel.SetColor(canvas.Ink);SyncColour();UpdateTaperControls();canvas.RefreshCursor();}
    void LoadTools(){preferencePath=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ID Sketcher","tools.xml");if(!Environment.GetCommandLineArgs().Any(a=>a=="--self-test"||a=="--preview"||a=="--tools-test")){try{preferences=ToolPreferences.Load(preferencePath);}catch(Exception ex){preferenceError="Saved tools could not be loaded: "+ex.Message;}}foreach(string n in new[]{"Select","Pencil","Pen","Ink Pen","Marker","Airbrush","Paintbrush","Eraser"})toolSettings[n]=n=="Airbrush"?new ToolPreset{Tool=n,Size=50,Flow=35,Hardness=0}:n=="Eraser"?new ToolPreset{Tool=n,Size=25}:n=="Paintbrush"?new ToolPreset{Tool=n,Size=24,Flow=35,Hardness=60}:new ToolPreset{Tool=n};foreach(var t in preferences.Tools)toolSettings[t.Tool]=t.Copy();foreach(var preset in toolSettings.Values)preset.Colour=Color.FromArgb(51,51,51).ToArgb();toolSettings["Marker"].Colour=Color.FromArgb(128,128,128).ToArgb();toolSettings["Airbrush"].Colour=Color.FromArgb(128,128,128).ToArgb();toolSettings["Eraser"].Size=25;ResetStartupPressure();pointSpacing.Value=Math.Max(10,Math.Min(50,preferences.VectorSpacingPercent));ApplyTool(toolSettings[canvas.Tool]);toolReady=true;}
    void ResetStartupPressure(){foreach(string name in new[]{"Pencil","Pen","Ink Pen"}){toolSettings[name].Pressure="Simulated pressure";toolSettings[name].Taper=50;}}
    bool SaveTools(){if(previewing)return true;preferences.VectorSpacingPercent=pointSpacing.Value;toolSettings[canvas.Tool]=CaptureTool();preferences.Tools=new List<ToolPreset>(toolSettings.Values);try{preferences.Save(preferencePath);return true;}catch(Exception ex){MessageBox.Show(this,"Tool settings could not be saved. "+ex.Message,"IDeaSKETCHER");return false;}}
    void PinFavourite(int slot){if(slot<0){slot=0;while(slot<24&&preferences.Favourites.Exists(f=>f.Slot==slot))slot++;}if(slot>=24||preferences.Favourites.Exists(f=>f.Slot==slot))return;var favourite=new Favourite{Slot=slot,Preset=CaptureTool()};preferences.Favourites.Add(favourite);if(!SaveTools())preferences.Favourites.Remove(favourite);}
    void RemoveFavourite(Favourite f){preferences.Favourites.Remove(f);if(!SaveTools())preferences.Favourites.Add(f);}
    void ChooseFavourite(Favourite f){SelectTool(f.Preset.Tool);ApplyTool(f.Preset.Copy());toolSettings[canvas.Tool]=CaptureTool();}
    public void TestPresets(){SelectTool("Pencil");size.Value=17;flow.Value=23;hardness.Value=41;smoothingSlider.Value=67;pressureMode.SelectedIndex=0;taperSlider.Value=29;canvas.Ink=Color.Orange;SelectTool("Pen");size.Value=11;SelectTool("Pencil");if(size.Value!=17||flow.Value!=23||hardness.Value!=41||smoothingSlider.Value!=67||pressureMode.SelectedIndex!=0||taperSlider.Value!=29||canvas.Ink.ToArgb()!=Color.Orange.ToArgb())throw new Exception("Per-tool settings");PinFavourite(0);size.Value=9;ChooseFavourite(preferences.Favourites[0]);if(size.Value!=17)throw new Exception("Favourite snapshot");for(int i=1;i<24;i++)PinFavourite(i);PinFavourite(-1);if(preferences.Favourites.Count!=24)throw new Exception("Favourite limit");string p=Path.Combine(Path.GetTempPath(),"IDSketcher-test-"+Guid.NewGuid()+".xml");try{preferences.Tools=new List<ToolPreset>(toolSettings.Values);preferences.Save(p);var loaded=ToolPreferences.Load(p);if(loaded.Tools.Count!=8||loaded.Tools.Find(t=>t.Tool=="Pencil").Size!=17||loaded.Favourites.Count!=24||loaded.Favourites[0].Preset.Size!=17||loaded.Favourites[0].Preset.Colour!=Color.Orange.ToArgb())throw new Exception("Favourite persistence");loaded.Save(p);if(ToolPreferences.Load(p).Favourites.Count!=24)throw new Exception("Preference replacement");}finally{if(File.Exists(p))File.Delete(p);}canvas.TestRightClick();var cells=brushPopup.Content.Controls.OfType<FavouriteButton>().OrderBy(b=>b.Slot).ToArray();if(cells.Length!=24||cells[7].Top!=cells[0].Top||cells[8].Top<=cells[0].Top||cells[23].Left!=cells[7].Left)throw new Exception("Favourite grid must be 3 rows by 8 columns");RemoveFavourite(preferences.Favourites.Find(f=>f.Slot==23));brushPopup.Close();canvas.TestRightClick();cells=brushPopup.Content.Controls.OfType<FavouriteButton>().OrderBy(b=>b.Slot).ToArray();cells[23].PerformClick();if(preferences.Favourites.Count!=24)throw new Exception("Pin empty slot");size.Value=8;cells[0].PerformClick();if(size.Value!=17)throw new Exception("Favourite button recall");brushPopup.Close();preferences.Favourites.Clear();dirty=false;}
}
}
